def load() -> pd.DataFrame:
    import glob
    html_file = 'data/legal/input/metropolitan_statistics.html'
    tables = pd.read_html(html_file)

    results = []
    for table in tables:
        if table.empty:
            continue

        # Flatten multi-index columns if present
        if isinstance(table.columns, pd.MultiIndex):
            table.columns = ['_'.join(str(c).strip() for c in col if c).strip('_') for col in table.columns]

        # Convert all column names to strings for comparison
        col_names = [str(c) for c in table.columns]

        # Look for patterns indicating MSA name and population columns
        has_msa = any('metropolitan' in str(c).lower() or 'area' in str(c).lower() for c in col_names)
        has_pop = any('2024' in str(c) or '2020' in str(c) or 'population' in str(c).lower() or 'census' in str(c).lower() for c in col_names)

        if not (has_msa and has_pop):
            continue

        # Find relevant columns
        msa_col = None
        pop_2024_col = None
        pop_2020_col = None

        for col in col_names:
            col_lower = str(col).lower()
            if msa_col is None and ('metropolitan' in col_lower or 'msa' in col_lower) and 'area' in col_lower:
                msa_col = col
            elif pop_2024_col is None and '2024' in col:
                pop_2024_col = col
            elif pop_2020_col is None and '2020' in col:
                pop_2020_col = col

        if msa_col is None:
            continue

        # Extract the relevant columns
        extract_cols = [msa_col]
        if pop_2024_col:
            extract_cols.append(pop_2024_col)
        if pop_2020_col:
            extract_cols.append(pop_2020_col)

        df = table[extract_cols].copy()
        df.columns = ['msa_name'] + df.columns[1:].tolist()

        # Clean MSA names - convert to string and strip
        df['msa_name'] = df['msa_name'].astype(str).str.strip()
        df = df[df['msa_name'].notna()]
        df = df[df['msa_name'] != '']
        df = df[df['msa_name'] != 'nan']

        # Try to convert population columns to numeric
        for col in df.columns[1:]:
            df[col] = pd.to_numeric(df[col], errors='coerce')

        df = df.dropna(subset=['msa_name'])
        if len(df) > 0:
            results.append(df)

    if results:
        return pd.concat(results, ignore_index=True)
    else:
        return pd.DataFrame(columns=['msa_name', '2024 estimate', '2020 census'])
